(() => {
'use strict';
const $=id=>document.getElementById(id);let tab='map',item='potion',dialogue=null,heroAngle=0,heroKey='';const keeper=new Image();let keeperRects=[];
const g=()=>window.gameDebug;
const classes=['Следопыт','Волшебник','Воин'];
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b}
function switchTab(next){if(next==='test'&&g()?.state.world){window.Worlds.workshop();return;}tab=next;document.body.classList.toggle('workshop-open',next==='test');for(const name of['map','hero','bag','test']){$(name+'-view').hidden=name!==tab;$('tab-'+name).classList.toggle('active',name===tab);$('tab-'+name).setAttribute('aria-selected',String(name===tab))}if(tab!=='map')$('title').textContent=tab==='test'?'Мастерская':tab==='hero'?'Герой':'Рюкзак';else g().render();renderViews();window.HUD?.render()}
function selectHero(step){if(g().busy||g().state.combat)return;const s=g().state,alive=s.party.filter(p=>p.hp>0);if(!alive.length)return;const i=alive.findIndex(p=>p.id===s.active);s.active=alive[(i+step+alive.length)%alive.length].id;g().save();g().render()}
function paintHero(){const s=g().state,a=g().active();$('hero-name').textContent=a.name;$('hero-class').textContent=a.className||classes[a.kind];$('hero-level').textContent='Уровень '+s.level;paintHeroArt(a);const threshold=DND.xp[s.level]||Infinity,percent=Math.min(100,Math.max(0,(s.xp-DND.xp[s.level-1])/(threshold-DND.xp[s.level-1])*100));$('hero-progress').innerHTML='<div><span>Опыт</span><div class="hp-track"><i style="width:'+percent+'%"></i></div><b>'+s.xp+' / '+threshold+'</b></div><div><span>Здоровье</span><div class="hp-track"><i style="width:'+a.hp/a.max*100+'%"></i></div><b>'+a.hp+' / '+a.max+'</b></div>';
$('hero-stats').innerHTML=Object.entries(a.stats).map(([key,value])=>'<div><small>'+DND.labels[key]+'</small><b>'+value+'</b><span>'+(DND.mod(value)>=0?'+':'')+DND.mod(value)+'</span></div>').join('');$('equipment').replaceChildren();if(a.kind===0&&!a.classId){for(const weapon of[{id:'bow',label:'Лук',icon:'🏹',range:30,damage:8},{id:'sword',label:'Короткий меч',icon:'⚔',range:1,damage:6}]){const b=button('',()=>{if(g().state.combat&&a.acted)return;window.Torches.equip(weapon.id==='bow'?['bow','bow']:['sword','empty'])});b.innerHTML='<b>'+weapon.label+'</b><small>'+weapon.range+' кл. · d'+weapon.damage+' +'+DND.mod(a.stats.dex)+'</small>';const icon=g().art(weapon.id==='bow'?31:32,'portrait');icon.className='item-art';b.prepend(icon);b.className='gear '+((a.weapon||'sword')===weapon.id?'equipped':'');b.disabled=g().busy||(s.combat&&a.acted);$('equipment').append(b)}}else{const b=document.createElement('div');b.className='gear equipped';b.innerHTML='<b>'+(a.classId?DND.weapon(a,s.level).name:a.kind===1?'Посох · луч':a.hands?.includes('shield')?'Меч и щит':'Длинный меч')+'</b><small>'+DND.weapon(a,s.level).range+' кл. · '+(DND.weapon(a,s.level).count||1)+'d'+DND.weapon(a,s.level).die+(DND.weapon(a,s.level).damageBonus>=0?' +':' ')+DND.weapon(a,s.level).damageBonus+' · атака '+(DND.weapon(a,s.level).attackBonus>=0?'+':'')+DND.weapon(a,s.level).attackBonus+' · '+DND.weapon(a,s.level).type+'</small>';const icon=g().art(a.classId==='cleric'?51:a.kind===1?33:32,'portrait');icon.className='item-art';b.prepend(icon);$('equipment').append(b)}
let history=$('hero-history');if(!history){history=document.createElement('p');history.id='hero-history';history.className='hero-history';$('hero-action-note').after(history);}history.textContent=a.background||'';let hands=document.getElementById('hero-hands');if(!hands){hands=document.createElement('section');hands.id='hero-hands';hands.className='hand-panel';$('equipment').after(hands);}window.Torches.fillHands(hands);$('level-up').textContent=s.xp>=threshold?'Повысить уровень':'Повысить уровень · ещё '+(threshold-s.xp)+' опыта';window.UIIcons.apply($('level-up'),'up');$('level-up').disabled=s.xp<threshold||g().busy||s.combat;$('hero-action-note').replaceChildren();const resources=[['Защита',a.ac,'Противник должен получить не меньше этого числа проверкой атаки. Щит добавляет 2.'],['Бонус владения','+'+DND.pb(s.level),'Добавляется к проверкам навыков и атакам, которыми владеет герой.'],...(a.maxSlots?[['Заклинания',a.slots+' / '+a.maxSlots,'Столько заклинаний с расходом ячейки осталось до отдыха. Базовые заговоры не тратят ячейки.']]:[]),['Кости восстановления',a.hitDice+' / '+a.maxHitDice,'На коротком отдыхе можно потратить кость класса и восстановить здоровье.']];for(const [name,value,explanation]of resources){const b=button('',()=>{const d=$('modal');$('modal-title').textContent=name;$('modal-body').textContent=explanation;d.showModal();});b.className='hero-resource';const title=document.createElement('span'),number=document.createElement('b');title.textContent=name;number.textContent=value;b.append(title,number);$('hero-action-note').append(b);}}
function paintHeroArt(a=g().active()){const key=JSON.stringify([a.id,a.appearance,a.hands,heroAngle]);if(key===heroKey)return;heroKey=key;$('hero-art').replaceChildren(window.voxel?.heroPortrait?voxel.heroPortrait(a,heroAngle):g().art(a.kind*4));}
function rotateHero(delta){heroAngle+=delta;paintHeroArt();}

function levelUp(){const s=g().state;if(s.combat||s.xp<(DND.xp[s.level]||Infinity)||g().busy)return;s.level++;for(const a of s.party){const gain=Math.floor(a.hitDie/2)+1+DND.mod(a.stats.con);a.max+=gain;if(a.hp>0)a.hp=a.max;a.maxHitDice=s.level;a.hitDice++;if(a.kind===1){a.maxSlots=s.level===2?3:4;a.slots=a.maxSlots;}if(s.level===4){a.stats[a.classId==='cleric'?'wis':a.kind===1?'int':a.kind===0?'dex':'str']=Math.min(20,a.stats[a.classId==='cleric'?'wis':a.kind===1?'int':a.kind===0?'dex':'str']+2);}}g().tell('Отряд достиг уровня '+s.level+'. Здоровье увеличено по кости класса и модификатору Телосложения.');g().render()}
function itemArtId(it){if(!it.id.startsWith('gear'))return({torch:37,potion:34,coins:35,letter:36,journal:40,relic:18})[it.id]??54;const name=it.name.toLowerCase();for(const [pattern,id]of [[/меч/,32],[/посох/,33],[/книга/,40],[/фокус/,41],[/рюкзак/,42],[/чернила|перо/,43],[/рацион/,44],[/щит/,45],[/кольч|броня/,46],[/верёв/,47],[/воровск/,48],[/одеяло/,49],[/разведения огня/,50],[/булава/,51],[/символ/,52],[/бинты/,53],[/мел/,54]])if(pattern.test(name))return id;return 42;}
function items(){const s=g().state,a=g().active();return [...InventoryRules.gearEntries(a).map(it=>({...it,name:/рацион/i.test(it.name)?'Дорожная еда':it.name,category:it.equipped?'Надето':'Снаряжение',description:/рацион/i.test(it.name)?'Комплект из пяти дневных порций еды. Расход еды пока не включён. Можно передать или выбросить.':/чернила|перо/i.test(it.name)?'Чернила и перо из стартового комплекта. Подходят для будущих записок. Сейчас можно передать или выбросить.':'Обычное снаряжение. '+(it.equipped?'Сначала снимите предмет в рюкзак, чтобы выбросить или передать его.':'Можно выбросить на свободную клетку или передать NPC.')})),...(a.torches?[{id:'torch',name:'Факел',amount:a.torches,equipped:a.hands.includes('torch')&&a.torches===1,category:'Источник света',description:'Одна рука. Можно зажечь, погасить, убрать или повесить на свободное крепление. Факел в руке даёт помеху атаке по правилам этой игры.'}]:[]),...(s.potions?[{id:'potion',name:'Лечебное зелье',amount:s.potions,category:'Расходник',description:'Восстанавливает 2d4 + 2 здоровья. В бою тратит бонусное действие.'}]:[])];}

function itemPicture(it){const name=it.name.toLowerCase(),key=/еда|рацион/.test(name)?'ration':/чернила|перо/.test(name)?'ink':/верёв/.test(name)?'rope':/рюкзак/.test(name)?'pack':/письмо/.test(name)?'letter':/меч/.test(name)?'sword':/щит/.test(name)?'shield':null;return key?window.Artwork.image(key,'item-art'):g().art(itemArtId(it),'portrait');}
function paintBag(){const list=items(),selected=list.find(i=>i.id===item)||list[0];item=selected?.id||'';$('bag-gold').textContent=g().state.gold+' монет';let count=$('bag-capacity');if(!count){count=document.createElement('span');count.id='bag-capacity';$('bag-gold').before(count);}count.textContent=InventoryRules.slotsUsed(g().active(),g().state)+' / 20';const host=$('bag-items');host.replaceChildren();const bag=list.filter(it=>!it.equipped),equipped=list.filter(it=>it.equipped);function itemButton(it){const b=button('',()=>{item=it.id;paintBag()});b.className='bag-item '+(item===it.id?'selected':'');b.title=it.name;b.setAttribute('aria-label',it.name+' · '+it.amount);const name=document.createElement('b'),amount=document.createElement('small');name.textContent=it.name;amount.textContent=String(it.amount);const icon=itemPicture(it);icon.className='item-art';b.append(icon,name,amount);return b;}for(const it of bag)host.append(itemButton(it));for(let i=bag.length;i<20;i++){const empty=document.createElement('div');empty.className='bag-empty';empty.setAttribute('aria-label','Свободная ячейка');host.append(empty);}let worn=$('bag-equipped');if(!worn){worn=document.createElement('div');worn.id='bag-equipped';host.after(worn);}worn.replaceChildren();if(equipped.length){const title=document.createElement('span');title.textContent='На герое';worn.append(title);for(const it of equipped)worn.append(itemButton(it));}const detail=$('item-detail');detail.replaceChildren();if(!selected){const p=document.createElement('p');p.textContent='Рюкзак пуст. Выберите предмет на карте, чтобы подобрать его.';detail.append(p);return;}const category=document.createElement('span'),icon=document.createElement('div'),title=document.createElement('h2'),description=document.createElement('p'),actions=document.createElement('div');category.className='item-category';category.textContent=selected.category;icon.id='item-icon';icon.className='item-icon';icon.append(itemPicture(selected));title.textContent=selected.name;description.textContent=selected.description;actions.id='item-actions';actions.className='options';detail.append(category,icon,title,description,actions);window.Inventory.controls(selected,actions);if(selected.id==='torch')window.Torches.inventory(actions);if(selected.id==='potion'){const b=button('Выпить зелье',()=>g().potion());b.disabled=$('potion').disabled;window.UIIcons.apply(b,'potion');actions.append(b);}}

function renderViews(){if(!g())return;if(tab==='hero'){paintHero();$('title').textContent=tab==='test'?'Мастерская':tab==='hero'?'Герой':'Рюкзак'}if(tab==='test')window.renderTests?.();if(tab==='bag'){paintBag();$('title').textContent=tab==='test'?'Мастерская':tab==='hero'?'Герой':'Рюкзак'}if(dialogue)paintDialogue()}
function drawKeeper(c,mode='portrait'){const miniature=mode==='prop';c.width=miniature?128:256;c.height=miniature?160:320;const cx=c.getContext('2d');cx.clearRect(0,0,c.width,c.height);cx.setTransform(miniature?.5:1,0,0,miniature?.5:1,0,0);const r=keeperRects[mode==='portrait'?0:1];if(!r)return;const scale=mode==='prop'?Math.min(184/r.w,250/r.h):Math.min(230/r.w,305/r.h),w=r.w*scale,h=r.h*scale;cx.drawImage(keeper,r.sx,r.sy,r.w,r.h,128-w/2,mode==='prop'?320/1.45-h*.81:160-h/2,w,h)}
function keeperCanvas(){const c=document.createElement('canvas');c.className='sprite keeper-portrait';c.width=640;c.height=720;const r=keeperRects[0];if(r){const cx=c.getContext('2d'),scale=Math.min(620/r.w,700/r.h),w=r.w*scale,h=r.h*scale;cx.drawImage(keeper,r.sx,r.sy,r.w,r.h,(640-w)/2,720-h,w,h);}return c}
function novicePortrait(){const box=document.createElement('div');box.className='npc-bust';box.innerHTML='<svg viewBox="0 0 180 220" aria-label="Лин, послушник" role="img"><defs><linearGradient id="lin-robe" x2="1" y2="1"><stop stop-color="#bd7755"/><stop offset="1" stop-color="#61332d"/></linearGradient></defs><path d="M19 218 28 143 58 125h64l30 18 12 75Z" fill="url(#lin-robe)" stroke="#352727" stroke-width="4"/><path d="M39 146 25 104 31 61Q43 13 92 15q52 2 61 51l5 42-19 43-19-30H59Z" fill="#d5be91" stroke="#49352d" stroke-width="4"/><path d="M49 74Q49 37 91 39q43 0 42 43v23q-2 42-41 46-42-5-43-48Z" fill="#efc29b"/><path d="M46 88Q38 36 89 33q45 0 48 52l-16-21-10 10-15-21-19 18-17-4Z" fill="#725032"/><path d="M53 78q7-28 21-31M127 77q-5-20-17-28" stroke="#ac7951" stroke-width="5" fill="none"/><ellipse cx="73" cy="99" rx="5" ry="8" fill="#342b2a"/><ellipse cx="110" cy="99" rx="5" ry="8" fill="#342b2a"/><path d="m70 85 10-2m25 0 10 3M86 123q7 5 14-1" stroke="#6f4031" stroke-width="3" fill="none" stroke-linecap="round"/><path d="m35 139 43 25 14-11 15 11 39-25-21 46-33-13-36 14Z" fill="#e0c9a0" stroke="#6f4f35" stroke-width="3"/><path d="M89 164h8v18h13v7H97v22h-8v-22H76v-7h13Z" fill="#d5a952" stroke="#7f5b2e" stroke-width="2"/><path d="m36 211 33-14 17 21m59-7-32-14-17 21" fill="#e8b68a" stroke="#533629" stroke-width="3"/></svg>';return box;}
function dialogueLine(text,options,name='Эллен · хранительница',portrait=true){dialogue={text,options,name,portrait};paintDialogue()}
function paintDialogue(){if(!dialogue)return;const panel=$('dialogue'),npc=/^(Эллен|Лин)/.test(dialogue.name);panel.classList.toggle('object-dialogue',!npc);const card=panel.querySelector('.speaker-card');let identity=card.querySelector('.speaker-identity');if(!identity){identity=document.createElement('div');identity.className='speaker-identity';const art=$('speaker-art'),copy=card.querySelector('.speaker-copy');identity.append(art);let caption=$('speaker-caption');if(!caption){caption=document.createElement('div');caption.id='speaker-caption';}identity.append(caption);card.replaceChildren(identity,copy);}const caption=$('speaker-caption'),name=dialogue.name.split(' · ');caption.replaceChildren();const title=document.createElement('b');title.textContent=name[0];caption.append(title);if(name[1]){const role=document.createElement('small');role.textContent=name.slice(1).join(' · ');caption.append(role);}$('speaker-name').hidden=true;$('speaker-name').textContent='';const art=$('speaker-art'),key=dialogue.name+':'+(dialogue.objectType||'npc');if(art.dataset.portrait!==key){art.dataset.portrait=key;art.replaceChildren(npc?window.Artwork.npc(dialogue.name):window.Artwork.image(({books:'books',chest:'chest',barrel:'barrel',desk:'desk',torch:'torch',crate:'pack'})[dialogue.objectType]||'book','object-portrait'));}const text=$('dialogue-text');if(text.textContent!==dialogue.text){text.textContent=dialogue.text;text.scrollTop=0;}$('dialogue-options').replaceChildren();for(const option of dialogue.options){const b=button(option.label,()=>{});b.disabled=!!option.disabled||!!window.HUD?.pending;b.onclick=async()=>{if(window.HUD?.pending)return;const previous=dialogue;if(previous){previous.text='';previous.options=[];paintDialogue();}try{await option.fn();}finally{if(dialogue===previous&&dialogue&&!dialogue.text)closeDialogue();}};$('dialogue-options').append(b);}panel.hidden=false;$('map-view').classList.add('dialogue-open');}

function closeDialogue(){dialogue=null;$('dialogue').hidden=true;document.getElementById('map-view').classList.remove('dialogue-open')}
function recordReply(question,response){g().tell('Вы: «'+question+'» Эллен: «'+response+'»');g().render();dialogueLine(response,[{label:'Задать другой вопрос',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openKeeper(){closeDialogue();if(g().state.episode&&(g().state.world||g().state.episode.stage!=='done')){window.Episode.ask();return;}window.Scenario?.talk();switchTab('map');dialogueLine(g().state.trial?.step===5?'Это моё потерянное письмо! Спасибо. Запись подтверждает: колокол увезли на север. Вы проверили свет, руки, дверь, тайник и разговор.':'Добро пожаловать в моё ателье. Здесь можно спокойно проверить предметы, потренироваться и подготовиться к следующему путешествию.',[
{label:'Расскажи об этом месте?',fn:()=>{const s=g().state;s.clues=s.clues||[];if(!s.clues.includes('courier'))s.clues.push('courier');recordReply('Расскажи об этом месте?','Библиотека находится здесь, за правой дверью — тренировочный зал. Северный проход ведёт в крипту. Каждый сундук и разговор можно восстановить во вкладке «Тест».')}},
{label:'Расскажи о крипте?',fn:()=>recordReply('Расскажи о крипте?','В крипте есть второй алтарь, архив и сундук. Возвращайтесь через дверь у южной стены: отряд перейдёт вместе с вами.')},
{label:'Попросить довериться · убеждение d20',fn:persuade},
{label:'У меня нет времени',fn:()=>{g().tell('Вы прервали разговор с Эллен. К её вопросам можно вернуться позже.');g().render();closeDialogue()}}]);}
async function persuade(){const s=g().state;if(s.persuasionAttempted){dialogueLine(s.secretKnown?'Я уже сказала вам о тайнике за книгами. Больше мне добавить нечего.':'Я пока не готова доверять вам больше. Но основные ответы я уже дала.',[{label:'Другой вопрос',fn:openKeeper},{label:'Закончить',fn:closeDialogue}]);return}const check=DND.skill(g().active(),'persuasion',12,s.level,s.advantage||0),n=check.natural,bonus=check.bonus,ok=check.success;g().report(check.text);await window.HUD?.check(check,'Убеждение');s.persuasionAttempted=true;s.secretKnown=ok;if(ok)s.xp+=10;const response=ok?'Я доверюсь вам. За книгами у настоятеля спрятан список имён. Найдите его, когда доберётесь до монастыря.':'Простите. Я слишком мало вас знаю, чтобы рисковать чужими жизнями.';g().tell('Убеждение: d20 '+n+' + '+bonus+' против 12 — '+(ok?'успех. +10 опыта.':'неудача.')+' Эллен: «'+response+'»');g().render();dialogueLine(response,[{label:'Вернуться к вопросам',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openNarrator(){switchTab('map');dialogueLine('Это личный визуальный полигон. Эллен ждёт в библиотеке, манекены — в правом крыле. Предметы и бой можно сбрасывать.',[{label:'Показать Эллен',fn:()=>{closeDialogue();g().test('npc');window.camera?.center(g().active(),true)}},{label:'Проверить диалог',fn:openKeeper},{label:'Как управлять?',fn:()=>g().help()},{label:'Хроника проверок',fn:()=>g().journal()}],'Ведущий',false)}
function openObject(p){closeDialogue();if(p.description){dialogueLine(p.description,[{label:'Вернуться к исследованию',fn:closeDialogue}],p.name,false);dialogue.objectType=p.type;paintDialogue();return;}dialogueLine(p.type==='books'?'На полках стоят книги по алхимии и старые путевые заметки. Среди страниц лежит закладка Эллен.':'На столе раскрыт журнал хранительницы. Рядом остывает воск от свечи.',[{label:'Прочитать заметку',fn:()=>dialogueLine('«Свет не должен ослеплять путника. Тень должна следовать за вещью, а шаг — приводить точно к её месту».',[{label:'Закрыть',fn:closeDialogue}],p.name,false)},{label:'Закрыть',fn:closeDialogue}],p.name,false);dialogue.objectType=p.type;paintDialogue();}
window.openObjectDialogue=openObject;

window.initViews=()=>{for(const name of['map','hero','bag','test'])$('tab-'+name).onclick=()=>switchTab(name);$('hero-prev').onclick=()=>rotateHero(-1);$('hero-next').onclick=()=>rotateHero(1);$('hero-prev').setAttribute('aria-label','Повернуть героя влево');$('hero-next').setAttribute('aria-label','Повернуть героя вправо');window.UIIcons.apply($('hero-prev'),'left');window.UIIcons.apply($('hero-next'),'right');let dragX=null;$('hero-art').addEventListener('pointerdown',e=>{dragX=e.clientX;$('hero-art').setPointerCapture?.(e.pointerId);});$('hero-art').addEventListener('pointermove',e=>{if(dragX===null)return;const delta=e.clientX-dragX;if(Math.abs(delta)>5){dragX=e.clientX;rotateHero(delta/100);}});for(const event of ['pointerup','pointercancel'])$('hero-art').addEventListener(event,()=>dragX=null);$('level-up').onclick=levelUp;$('dialogue-close').onclick=closeDialogue;renderViews()};
window.episodeDialogue=(text,options,name='Эллен · хранительница',portrait=true)=>{closeDialogue();switchTab('map');dialogueLine(text,options,name,portrait)};window.renderViews=renderViews;window.drawKeeper=drawKeeper;window.openKeeperDialogue=openKeeper;window.openNarratorDialogue=openNarrator;window.closeDialogue=closeDialogue;
keeper.onload=()=>{const c=document.createElement('canvas');c.width=keeper.width;c.height=keeper.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(keeper,0,0);keeperRects=[];for(let i=0;i<2;i++){const sx=i*keeper.width/2,w=Math.floor(keeper.width/2),h=keeper.height,a=cx.getImageData(sx,0,w,h).data;let l=w,t=h,r=0,b=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(a[(y*w+x)*4+3]>40){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y)}keeperRects.push({sx:sx+l,sy:t,w:r-l+1,h:b-t+1})}g()?.render()};keeper.src='assets/keeper.png';
window.viewsDebug={novicePortrait,rotateHero,items,switchTab,openKeeper,openNarrator,persuade,levelUp,get tab(){return tab}};
})();
